/** 分页获取对话 请求参数（POST /core/chat/record/getPaginationRecords） */
export type ChatRecordsListReq = {
  /** 偏移量，从 0 开始 */
  offset?: number;
  /** 应用 ID，使用接口允许的请求头凭证鉴权。 */
  appId?: string;
  /** 每页条数，默认 20，最大 500，超出自动按 500 处理 */
  pageSize?: number;
  /** 会话 ID */
  chatId?: string;
  /** 是否加载自定义反馈 */
  loadCustomFeedbacks?: boolean;
  /** 获取类型，影响数据过滤规则 */
  type?: 'normal' | 'outLink' | 'home';
  /** 是否包含已删除的记录 */
  includeDeleted?: boolean;
  /** 页码，从 1 开始；传入 offset 时忽略 */
  pageNum?: number;
  /** 仅普通应用的 API Key 调用支持。精确匹配对话的外部使用者 ID（outLinkUid），不匹配 tmbId；省略时保留原访问范围，传入时限制读取、修改及删除。最长 1024 字符，不接受空字符串或 null，不改变鉴权成员。 */
  customUid?: string;
  authProxy?:
    | {
        /** API Key 代理调用的团队成员 ID，优先于 username */
        tmbId: string;
      }
    | {
        /** API Key 代理调用的团队成员用户名 */
        username: string;
      };
};

/** 分页获取对话 响应数据（POST /core/chat/record/getPaginationRecords） */
export type ChatRecordsListRes = {
  /** 对话列表 */
  list: Array<Record<string, unknown>>;
  /** 总数 */
  total: number;
};

