/** 知识库搜索 请求参数（POST /core/dataset/search） */
export type DatasetsSearchReq = {
  /** 搜索范围 */
  scope: {
    /** 目标知识库 ID，最多 100 个；服务端去重，逐个校验读取权限 */
    datasetIds: string[];
    /** 集合与标签筛选，需要服务端提供筛选能力 */
    filter?: {
      /** 限制在这些集合或目录内搜索，与其他筛选条件求交集 */
      collectionIds?: string[];
      /** 集合创建时间范围 */
      createTime?: {
        /** 创建时间下界，含边界 */
        gte?: string;
        /** 创建时间上界，含边界 */
        lte?: string;
      };
      /** 标签条件；and 与 or 两组之间求交集 */
      tags?: {
        /** 全部满足的标签条件 */
        and?: Array<
          | {
              /** 标签名称 */
              tag: string;
              /** 标签是否为空 */
              op: '$empty' | '$notEmpty';
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 标量比较操作符 */
              op: '$eq' | '$ne' | '$gt' | '$lt' | '$gte' | '$lte';
              /** 标签比较值 */
              value: string | number;
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 包含比较操作符 */
              op: '$contains' | '$notContains';
              /** 匹配的文本或选项 */
              value: string | string[];
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 文本匹配操作符 */
              op: '$startsWith' | '$endsWith' | '$regex';
              /** 文本或正则表达式 */
              value: string;
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 数组比较操作符 */
              op: '$is' | '$isNot' | '$in' | '$notIn';
              /** 匹配的选项列表 */
              value: string[];
            }
        >;
        /** 至少满足一项的标签条件 */
        or?: Array<
          | {
              /** 标签名称 */
              tag: string;
              /** 标签是否为空 */
              op: '$empty' | '$notEmpty';
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 标量比较操作符 */
              op: '$eq' | '$ne' | '$gt' | '$lt' | '$gte' | '$lte';
              /** 标签比较值 */
              value: string | number;
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 包含比较操作符 */
              op: '$contains' | '$notContains';
              /** 匹配的文本或选项 */
              value: string | string[];
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 文本匹配操作符 */
              op: '$startsWith' | '$endsWith' | '$regex';
              /** 文本或正则表达式 */
              value: string;
            }
          | {
              /** 标签名称 */
              tag: string;
              /** 数组比较操作符 */
              op: '$is' | '$isNot' | '$in' | '$notIn';
              /** 匹配的选项列表 */
              value: string[];
            }
        >;
      };
    };
  };
  /** 搜索内容 */
  query:
    | {
        /** 查询文本，trim 后最多 10000 字符；与图片至少提供一项 */
        text: string;
        /** 本团队上传的临时图片对象 key，最多 10 张 */
        imageKeys?: string[];
      }
    | {
        /** 本团队上传的临时图片对象 key，最多 10 张 */
        imageKeys: string[];
        /** 查询文本，trim 后最多 10000 字符；与图片至少提供一项 */
        text?: string;
      };
  /** 召回配置 */
  retrieval?: {
    /** embedding、fullTextRecall 或 mixedRecall */
    mode?: 'embedding' | 'fullTextRecall' | 'mixedRecall';
    /** 混合检索中向量结果的融合权重 */
    embeddingWeight?: number;
  };
  /** 重排配置；关闭时不能传模型或权重 */
  rerank?:
    | {
        /** 关闭重排 */
        enabled: false;
      }
    | {
        /** 启用重排 */
        enabled: true;
        /** 模型 ID；省略时使用有权调用的默认模型 */
        modelId?: string;
        /** 重排候选数，范围 10–100；省略时使用默认值 100 */
        candidateNum?: number;
        /** 重排结果的融合权重 */
        weight?: number;
      };
  /** 查询扩展配置 */
  queryExtension?:
    | {
        /** 关闭查询扩展 */
        enabled: false;
      }
    | {
        /** 启用查询扩展 */
        enabled: true;
        /** 模型 ID；省略时使用有权调用的默认模型 */
        modelId?: string;
        /** 帮助模型理解查询的背景信息 */
        background?: string;
      };
  /** 条数和 token 预算二选一；未指定时默认 topk=20，不设置 token 预算 */
  result?:
    | {
        /** 结果总 token 预算，无业务上限；保留完整数据块，最后一块可能使预算超出 */
        maxTokens: number;
        /** 沿用检索分数阈值语义；是否生效以 usingSimilarityFilter 为准 */
        similarity?: number;
      }
    | {
        /** 返回排序后的前 k 条，范围 1–100；未传两种预算时默认 20，不做 token 过滤 */
        topk?: number;
        /** 沿用检索分数阈值语义；是否生效以 usingSimilarityFilter 为准 */
        similarity?: number;
      };
  /** 账单用途：search 显示知识库搜索，searchTest 显示搜索测试；不影响检索和权限 */
  usageScene?: 'search' | 'searchTest';
};

