/** 更新知识库 请求参数（PUT /core/dataset/update） */
export type DatasetsUpdateReq = {
  /** 知识库 ID */
  id: string;
  /** 父级文件夹 ID,传 null 表示移动到根目录 */
  parentId?: string | null;
  /** 知识库名称 */
  name?: string;
  /** 知识库头像 */
  avatar?: string;
  /** 知识库简介 */
  intro?: string;
  /** 知识库 Agent 模型 ID；未传不修改，不允许清空 */
  agentModelId?: string;
  /**
   * 旧版知识库 Agent 模型标识，仅未传 agentModelId 时使用
   * @deprecated
   */
  agentModel?: string;
  /** 视觉语言模型 ID；未传不修改，null 或空字符串表示清空 */
  vlmModelId?: string | null;
  /**
   * 旧版视觉语言模型标识，仅未传 vlmModelId 时使用；null 或空字符串表示清空
   * @deprecated
   */
  vlmModel?: string | null;
  /** 网站知识库配置 */
  websiteConfig?: {
    /** 网站 URL */
    url: string;
    /** 网站选择器 */
    selector: string;
  };
  /** 外部读取 URL */
  externalReadUrl?: string;
  /** 第三方知识库服务器配置(API/飞书/语雀/钉钉) */
  apiDatasetServer?: {
    /** API 服务器配置 */
    apiServer?: {
      baseUrl: string;
      authorization?: string;
      basePath?: string;
    };
    /** 飞书服务器配置 */
    feishuServer?: {
      appId: string;
      appSecret?: string;
      folderToken: string;
    };
    /** 语雀服务器配置 */
    yuqueServer?: {
      userId: string;
      token?: string;
      basePath?: string;
    };
    /** 钉钉知识库配置 */
    dingtalkServer?: {
      appKey: string;
      appSecret?: string;
      userId: string;
      operatorId?: string;
      workspaceId?: string;
      rootNodeId?: string;
      workspaceName?: string;
    };
    /** 外部文件权限同步。仅 custom apiServer 支持；开启即由外部列表全量接管 collection ACL */
    permissionSync?: boolean;
  };
  /** 是否自动同步 */
  autoSync?: boolean;
  /** 是否开启第三方知识库整库全量同步（仅 API 知识库生效；开启后会同时恢复库内所有已暂停同步的子目录） */
  syncAll?: boolean;
  /** 分块配置 */
  chunkSettings?: {
    /** 训练类型 */
    trainingType?: 'chunk' | 'qa' | 'imageParse' | 'backup' | 'template' | 'auto';
    /** 分块触发时机 */
    chunkTriggerType?: 'minSize' | 'forceChunk' | 'maxSize';
    /** 分块触发最小大小 */
    chunkTriggerMinSize?: number;
    /** 增加集合名到分块里 */
    dataEnhanceCollectionName?: boolean;
    /** 图片索引 */
    imageIndex?: boolean;
    /** 自动生成索引 */
    autoIndexes?: boolean;
    /** 索引前缀标题 */
    indexPrefixTitle?: boolean;
    /** 系统参数/自定义参数 */
    chunkSettingMode?: 'auto' | 'custom' | 'intelligent';
    /** 分块拆分模式 */
    chunkSplitMode?: 'paragraph' | 'size' | 'char';
    /** 段落分块 AI 模式 */
    paragraphChunkAIMode?: 'auto' | 'force' | 'forbid';
    /** 段落分块深度 */
    paragraphChunkDeep?: number;
    /** 段落分块最小大小 */
    paragraphChunkMinSize?: number;
    /** 分块大小 */
    chunkSize?: number;
    /** 自定义最高优先分割符号 */
    chunkSplitter?: string;
    /** 索引大小 */
    indexSize?: number;
    /** QA 拆分提示词 */
    qaPrompt?: string;
  };
  /** 外部文档解析开关(页眉页脚/附录/图片识别/图转表),仅对 customPdfParse 解析路径生效;编辑后仅对新解析的文件生效 */
  sangforFileParseConfig?: {
    /** 是否保留页眉页脚，默认关闭（删除页眉页脚） */
    keep_header_footer?: boolean;
    /** 是否保留附录，默认开启 */
    keep_appendix?: boolean;
    /** 是否保留图片识别（含印章）结果，默认关闭 */
    image_analysis?: boolean;
    /** 是否保留图表转表格结果（同时保留原图片），默认关闭 */
    chart_analysis?: boolean;
  };
};

